import hljs from 'highlight.js/lib/core';
import type { LanguageFn } from 'highlight.js';
import chalk from 'chalk';
import indexJson from './hljs-languages.json' with { type: 'json' };
import type { Highlighter, Style } from './types.ts';

interface LanguageIndex {
  names: string[];
  aliases: Record<string, string>;
  embeds: Record<string, string[]>;
}
// generated by scripts/hljs-languages.ts (`bun run gen:languages`)
const index: LanguageIndex = indexJson;

const names = new Set(index.names);
const resolve = (lang: string | undefined): string | undefined => {
  const name = lang?.toLowerCase();
  if (name === undefined) return undefined;
  return names.has(name) ? name : index.aliases[name];
};
const isLanguageFn = (value: unknown): value is LanguageFn => typeof value === 'function';

function load(name: string): void {
  if (hljs.getLanguage(name)) return;
  const definition: unknown = import.meta.require(`highlight.js/lib/languages/${name}`);
  if (!isLanguageFn(definition)) throw new TypeError(`highlight.js/lib/languages/${name} doesn't export a language`);
  hljs.registerLanguage(name, definition);
  for (const other of index.embeds[name] ?? []) load(other);
}

const plain: Style = (s) => s;

// Scope → style, same palette Claude Code applies to highlight.js output.
const styles = new Map<string, Style>(
  Object.entries({
    keyword: chalk.blue,
    built_in: chalk.cyan,
    type: chalk.cyan.dim,
    literal: chalk.blue,
    number: chalk.green,
    regexp: chalk.red,
    string: chalk.red,
    subst: plain,
    symbol: plain,
    class: chalk.blue,
    function: chalk.yellow,
    title: plain,
    'title.function': chalk.yellow,
    'title.class': chalk.blue,
    params: plain,
    comment: chalk.green,
    doctag: chalk.green,
    meta: chalk.grey,
    'meta.keyword': plain,
    'meta.string': plain,
    section: plain,
    tag: chalk.grey,
    name: chalk.blue,
    attr: chalk.cyan,
    attribute: plain,
    variable: plain,
    bullet: plain,
    code: plain,
    emphasis: chalk.italic,
    strong: chalk.bold,
    link: chalk.underline,
    quote: plain,
    addition: chalk.green,
    deletion: chalk.red,
  })
);

function styleFor(scope: string): Style | undefined {
  for (let s = scope; ; s = s.slice(0, s.lastIndexOf('.'))) {
    const style = styles.get(s);
    if (style) return style;
    if (!s.includes('.')) return undefined;
  }
}

const entities: Record<string, string> = { amp: '&', lt: '<', gt: '>', quot: '"', '#x27': "'", '#39': "'" };
const unescape = (s: string): string => s.replaceAll(/&(amp|lt|gt|quot|#x27|#39);/gu, (_, e: string) => entities[e] ?? '');

// highlight.js emits <span class="hljs-title function_">; that's scope "title.function"
function scopeOf(className: string): string {
  const [first = '', ...rest] = className.split(' ');
  return [first.replace(/^hljs-/u, ''), ...rest.map((c) => c.replace(/_+$/u, ''))].join('.');
}

function toAnsi(html: string): string {
  const root = { style: plain, text: '' };
  const stack = [root];
  const top = () => stack.at(-1) ?? root;
  for (const [, open, close, text = ''] of html.matchAll(/<span class="([^"]*)">|(<\/span>)|([^<]+)/gu)) {
    if (open !== undefined) stack.push({ style: styleFor(scopeOf(open)) ?? plain, text: '' });
    else if (close !== undefined && stack.length > 1) {
      const node = stack.pop() ?? root;
      top().text += node.style(node.text);
    } else top().text += unescape(text);
  }
  return root.text;
}

export const highlighter: Highlighter = {
  supportsLanguage: (lang) => resolve(lang) !== undefined,
  highlight(code, { language }) {
    // highlight.js logs a warning before throwing for an unknown language
    const name = resolve(language);
    if (name === undefined) return code;
    load(name);
    try {
      return toAnsi(hljs.highlight(code, { language: name, ignoreIllegals: true }).value);
    } catch {
      return code;
    }
  },
};
